def find_max(words):
    max_unique = 0
    result_word = ""

    for word in words:
        unique_count = len(set(word))

        if unique_count > max_unique:
            max_unique = unique_count
            result_word = word
        elif unique_count == max_unique and (result_word == "" or word < result_word):
            result_word = word

    return result_word
